import{d as c,C as t,o as g,c as u,j as a,a as o,E as n,a3 as m}from"./chunks/framework.Q4yG9rk_.js";const _=JSON.parse('{"title":"道德经第四十二章","description":"从道生一到损益与强梁之戒，循王弼有无之论理解生成、谦下和教戒。","frontmatter":{"title":"道德经第四十二章","description":"从道生一到损益与强梁之戒，循王弼有无之论理解生成、谦下和教戒。","category":"guide","aliases":["道德经第四十二章","老子第四十二章","dao de jing chapter 42"],"source":["王弼《道德真经注》卷三"]},"headers":[],"relativePath":"daoism/dao-de-jing/chapter-42.md","filePath":"daoism/dao-de-jing/chapter-42.md","lastUpdated":1794189804000}'),b={name:"daoism/dao-de-jing/chapter-42.md"},y=c({...b,setup(p){const s=[{id:"from-dao-to-many",label:"道生一",showLabel:!0,sentences:[["道生",{text:"一",glossary:"yi"},"，",{text:"一",glossary:"yi"},"生二，二生三，三生万物。"]],note:["【白话】道生出一，一再生二，二再生三，三生万物。依王弼读，万物虽有万形，却归于一；追问一的所由，又要返到无。一旦言说为一，便已形成分别，由此展开二、三与万物。","【王弼注择要】「万物万形，其归一也。何由致一？由于无也。」又说「有言有一，非二如何？有一有二，遂生乎三」，不只按物质生成次序解释数字。","【读法】把一、二、三分别讲成元气、阴阳、和气，是常见的另一条解释路径；后文确实谈到阴阳与冲气，但本页不把这一套直接冒称为王弼原注。此处是古代生成与根本之论，不能作为现代宇宙学结论。"]},{id:"yin-yang-harmony",label:"万物负阴而抱阳",showLabel:!0,sentences:[["万物负阴而抱阳，",{text:"冲气",glossary:"chongqi"},"以为和。"]],note:["【白话】万物背负阴而怀抱阳，由冲和之气形成和合。它们各有不同的形态，又在相反相成的关系中得到调和。","【王弼注择要】「虽有万形，冲气一焉。」注强调万形之中贯通的冲和，与前段归一相承。","【读法】负、抱取背负、怀抱的取象，不宜固定成每一物体的具体方位；气与阴阳属于古代解释语言，不直接等同于现代物理量。"]},{id:"loss-and-gain",label:"或损之而益",showLabel:!0,sentences:[["人之所",{text:"恶",glossary:"wu"},"，唯",{text:"孤",glossary:"gu"},"、",{text:"寡",glossary:"gua"},"、",{text:"不谷",glossary:"bugu"},"，而王公以为",{text:"称",glossary:"cheng"},"。故物或损之而益，或益之而损。"]],note:["【白话】人们所厌恶的，是孤、寡、不谷这些处于低下、少德的称呼，王公却拿来作自称。所以事物有时受到减损反而增益，有时看似增益却反而受损。","【王弼注择要】「愈多愈远，损则近之。」王弼将损益连到以一为主与返本，并以「损之而益，岂虚言也」反问收束。","【读法】或表示有的情形，并非所有减少必有回报、所有增加必有损失。谦称与第三十九章呼应，须看是否真能不自高、守住根本，不能靠一个称号判定。"]},{id:"teaching-through-natural-consequences",label:"人之所教，我亦教之",showLabel:!0,sentences:[["人之所教，我亦教之。"]],note:["【白话】别人所用来教戒的道理，我也用来教戒。依王弼，这样的教导是指出行事本有的后果，使人有所警觉，而非凭自己的强力要求服从。","【王弼注择要】「我之非强使人从之也，而用夫自然。」注由教的方式呼应前文不以强横求成。","【读法】人之所教须连下句强梁的例子读，不是无条件接受所有流行说法；本页对教法的现代启发也不取代知识判断。"]},{id:"warning-against-violence",label:"强梁者不得其死",showLabel:!0,sentences:[[{text:"强梁",glossary:"qiangliang"},"者不得其死，吾将以为",{text:"教父",glossary:"jiaofu"},"。"]],note:["【白话】强横逞暴的人，不能得到正常的终结、安然的死；我将把这一警戒作为教人的根本。强梁的后果在此成为反面教戒。","【王弼注择要】王弼将教戒归为「不当为强梁也」，并问「举其强梁不得其死以教耶」，仍在说明怎样以此教人。","【读法】不得其死是对强横后果的警句，不是命人杀死强梁者；教父也不是现代宗教称谓。不能据一个人的死法倒推其德行，更不宜用此归罪受害者。"]}],r=[{id:"yi",term:"一",sense:2},{id:"chongqi",term:"冲气",sense:1},{id:"wu",term:"恶",sense:1},{id:"gu",term:"孤",sense:1},{id:"gua",term:"寡",sense:1},{id:"bugu",term:"不谷",sense:1},{id:"cheng",term:"称",sense:1},{id:"qiangliang",term:"强梁",sense:1},{id:"jiaofu",term:"教父",sense:1}];return(x,e)=>{const i=t("DaoReadingPrelude"),l=t("DaoTextReading"),d=t("DaoLineGuide"),h=t("DaoKeywordCards");return g(),u("div",null,[e[0]||(e[0]=a("h1",{id:"道德经第四十二章",tabindex:"-1"},[o("道德经第四十二章 "),a("a",{class:"header-anchor",href:"#道德经第四十二章","aria-label":'Permalink to "道德经第四十二章"'},"​")],-1)),n(i,{title:"道生一怎样连到损益与强梁之戒",summary:"本章由道、一、二、三说到万物，再由阴阳冲和转入王公谦称、损益与强梁的教戒。王弼以由无入有、万形归一贯通前半，再以不强使人从解释教人的方式。",points:[{label:"先读",text:"一二三的解释有不同路径，本页先交代王弼从无至有与言说分别的读法。"},{label:"再辨",text:"王公的谦称与损益相连，但自称孤寡不等于已经谦下。"},{label:"后看",text:"强梁之戒用来反省强横，不能用作暴力处罚的授权。"}],hint:"恶读 wù，称读 chēng，强梁读 qiáng liáng；教父在这里指教戒的根本或起点。"}),e[1]||(e[1]=a("h2",{id:"【原典层】原文与段释义",tabindex:"-1"},[o("【原典层】原文与段释义 "),a("a",{class:"header-anchor",href:"#【原典层】原文与段释义","aria-label":'Permalink to "【原典层】原文与段释义"'},"​")],-1)),n(l,{sections:s,glossary:r}),e[2]||(e[2]=a("h2",{id:"【原典层】核心句引读",tabindex:"-1"},[o("【原典层】核心句引读 "),a("a",{class:"header-anchor",href:"#【原典层】核心句引读","aria-label":'Permalink to "【原典层】核心句引读"'},"​")],-1)),n(d,{lines:[{text:"道生一，一生二，二生三，三生万物。",tone:"从根本到万形",guide:"先循王弼由无至有、由言一而有分别的解释，不混为唯一的数字配物模型。"},{text:"故物或损之而益，或益之而损。",tone:"增减须看所依",guide:"或字保留具体条件，不把损益变成固定的交换保证。"},{text:"强梁者不得其死，吾将以为教父。",tone:"以强横为戒",guide:"教人反省强横的后果，同时检验教导本身是否强使人从。"}]}),e[3]||(e[3]=a("h2",{id:"【原典层】字词释义",tabindex:"-1"},[o("【原典层】字词释义 "),a("a",{class:"header-anchor",href:"#【原典层】字词释义","aria-label":'Permalink to "【原典层】字词释义"'},"​")],-1)),n(h,{items:r}),e[4]||(e[4]=m('<h2 id="【解读层】三问解读" tabindex="-1">【解读层】三问解读 <a class="header-anchor" href="#【解读层】三问解读" aria-label="Permalink to &quot;【解读层】三问解读&quot;">​</a></h2><h3 id="象-生成与强梁之戒为何在同一章" tabindex="-1">象：生成与强梁之戒为何在同一章？ <a class="header-anchor" href="#象-生成与强梁之戒为何在同一章" aria-label="Permalink to &quot;象：生成与强梁之戒为何在同一章？&quot;">​</a></h3><p>前半从万形追问根本与冲和，后半看谦下、损益及强横的后果。王弼以归一、减损而近本及不强使人从来衔接，不必把它们割成互不相干的宇宙论和处世格言。</p><h3 id="理-减损为什么可能成为增益" tabindex="-1">理：减损为什么可能成为增益？ <a class="header-anchor" href="#理-减损为什么可能成为增益" aria-label="Permalink to &quot;理：减损为什么可能成为增益？&quot;">​</a></h3><p>若减去的是自高与过度造作，可能使事物更接近所依的根本。若减去的是生存所需，却未必有益；或损之而益要求辨别减损的对象与情境。</p><h3 id="用-教导怎样避免重演强梁" tabindex="-1">用：教导怎样避免重演强梁？ <a class="header-anchor" href="#用-教导怎样避免重演强梁" aria-label="Permalink to &quot;用：教导怎样避免重演强梁？&quot;">​</a></h3><p>把理由、后果和可以检验的事实说清，给对方理解与回应的余地。不能一面引用强梁的警戒，一面用威压取代讨论。</p><h2 id="【解读层】现代解读与启发" tabindex="-1">【解读层】现代解读与启发 <a class="header-anchor" href="#【解读层】现代解读与启发" aria-label="Permalink to &quot;【解读层】现代解读与启发&quot;">​</a></h2><p><strong>先辨什么值得增加。</strong> 更多指标、资源与要求并不必然改善结果。判断增减时，回到它是否有助于事情成立；不把精简本身当作目的。</p><p><strong>让教戒也接受检验。</strong> 指出风险可以帮助人，但以灾祸恐吓、以服从证明正确，会把教导重新变成强制。解释后果时应给出依据，也允许修正。</p><h2 id="【个人记录】我的笔记" tabindex="-1">【个人记录】我的笔记 <a class="header-anchor" href="#【个人记录】我的笔记" aria-label="Permalink to &quot;【个人记录】我的笔记&quot;">​</a></h2><p>留给自己的续读问题：我想增加的东西，是否反而让我离根本更远？我在提醒别人时，是提供可理解的理由，还是只要求对方听从？</p><h2 id="校读说明与参考来源" tabindex="-1">校读说明与参考来源 <a class="header-anchor" href="#校读说明与参考来源" aria-label="Permalink to &quot;校读说明与参考来源&quot;">​</a></h2><ul><li>正文与标点沿本站保留，与卷三 007a–008a 电子录文相核；不穀按本站简化作不谷。</li><li>一另列本章由无入有、万形归一的义项，说明王弼数字与言说分别的取径；阴阳冲气不直接套用现代科学概念。</li><li>不得其死依教戒语境解释，不补成惩杀命令；王公谦称复用第三十九章词义，正文仍在本章语境中释读。</li></ul><p>参考：<a href="https://github.com/kanripo/KR5c0073/blob/b988441bd55861741c850e1dff4a2d4f895daf3d/KR5c0073_003.txt" target="_blank" rel="noreferrer">王弼《道德真经注》卷三 HFL 本电子录文，007a–008a</a>。</p>',15))])}}});export{_ as __pageData,y as default};
